"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def ComputeSumAndAverage(numbers):
    if (len(numbers) == 0):
        return (0, 0)
    total_sum = 0
    for num in numbers:
        total_sum = (total_sum + num)
    average = (total_sum / len(numbers))
    return (total_sum, average)
print(ComputeSumAndAverage([1, 2, 3]))